<?php
declare(strict_types=1);require_once __DIR__.'/../../includes/lacms_sync_helpers.php';requireLacmsPermission('lacms.sync.view');$rows=db()->query("SELECT s.sync_reference,s.title,s.sync_type,s.priority_level,s.status,o.name office_name,c.name committee_name,(SELECT COUNT(*) FROM lacms_sync_actions a WHERE a.sync_record_id=s.id) action_count,(SELECT COUNT(*) FROM lacms_sync_actions a WHERE a.sync_record_id=s.id AND a.status IN ('Pending','In Progress')) open_actions FROM lacms_sync_records s LEFT JOIN offices o ON o.id=s.source_office_id LEFT JOIN committees c ON c.id=s.target_committee_id ORDER BY s.updated_at DESC")->fetchAll();$pageTitle='Synchronization Report';$activeMenu='synchronization';$extraCss=[appUrl('assets/css/lacms-operational.css')];include __DIR__.'/../../layouts/header.php';?><div class="lacms-app-wrapper"><?php include __DIR__.'/../../layouts/sidebar.php'; ?><main class="lacms-main-content"><div class="lo-head"><div><div class="lo-eyebrow">Operational Report</div><h1>Executive-Legislative Synchronization Report</h1></div><a class="btn btn-outline-secondary" href="index.php">Registry</a></div><div class="card lo-card"><div class="table-responsive"><table class="table lo-table mb-0"><thead><tr><th>Reference</th><th>Title / Type</th><th>Executive Office</th><th>Legislative Committee</th><th>Priority</th><th>Actions</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['sync_reference']) ?></td><td><?= e($r['title']) ?><div class="small text-muted"><?= e($r['sync_type']) ?></div></td><td><?= e($r['office_name']?:'—') ?></td><td><?= e($r['committee_name']?:'—') ?></td><td><?= e($r['priority_level']) ?></td><td><?= (int)$r['action_count'] ?> / <?= (int)$r['open_actions'] ?> open</td><td><?= e($r['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></main></div><?php include __DIR__.'/../../layouts/footer.php'; ?>
